399	    /**
400	     * The owner's age band, derived on read from the {@link #birthDate} relative to the
401	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
402	     * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
403	     * date to measure against) is available.
404	     */
405	    @Transient
406	    public String getAgeBand() {
407	        if (this.birthDate == null || this.registrationDate == null) {
408	            return null;
409	        }
410	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
411	        if (age < 18) {
412	            return "MINOR";
413	        }
414	        if (age < 65) {
415	            return "ADULT";
416	        }
417	        return "SENIOR";
418	    }
419	
420	    /**
421	     * The single Luhn check digit (0-9) computed over the decimal digits contained in the
422	     * {@link #customerCode}, derived on read.
423	     */
424	    @Transient
425	    public Integer getCheckDigit() {
426	        return luhnCheckDigit(this.customerCode);
427	    }
428	
429	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
430	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
431	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
432	        "NSW", new int[] {2000, 2099},
433	        "VIC", new int[] {3000, 3099},
434	        "QLD", new int[] {4000, 4099});
435	
436	    /**
437	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
438	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
439	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
440	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
441	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
442	     */
443	    @Transient
444	    public String getRegion() {
445	        String byPostcode = regionForPostcode(this.postcode);
446	        if (byPostcode != null) {
447	            return byPostcode;
448	        }
449	        if ("Sydney".equals(this.city)) {
450	            return "NSW";
451	        }
452	        if ("Melbourne".equals(this.city)) {
453	            return "VIC";
454	        }
455	        if ("Brisbane".equals(this.city)) {
456	            return "QLD";
457	        }
458	        return "UNKNOWN";
459	    }
460	
461	    /**
462	     * The owner's locality, derived on read from the region-and-hash {@link #getCustomerCode()
463	     * customer code}: the region segment before the first '-' of the customer code
464	     * ('<REGION>-<HASH8>'). Falls back to the owner's {@link #getRegion() region} when no customer
465	     * code has been assigned yet.
466	     */
467	    @Transient
468	    public String getLocality() {
469	        if (this.customerCode != null) {
470	            int dash = this.customerCode.indexOf('-');
471	            if (dash > 0) {
472	                return this.customerCode.substring(0, dash);
473	            }
474	        }
475	        return getRegion();
476	    }
477	
478	    /** Region -> IANA timezone name, the fixed region-to-timezone table ({@code NSW ->
479	     *  Australia/Sydney}, {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
480	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
481	        "NSW", "Australia/Sydney",
482	        "VIC", "Australia/Melbourne",
483	        "QLD", "Australia/Brisbane");
484	
485	    /**
486	     * The owner's timezone, derived on read as the IANA name for the owner's
487	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table
488	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
489	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region carries no entry in
490	     * the table (e.g. {@code UNKNOWN}).
491	     */
492	    @Transient
493	    public String getTimezone() {
494	        return timezoneForRegion(getLocality());
495	    }
496	
497	    /**
498	     * The owner's segment, derived on read as {@code "<TIER>_<AREA>"}: one of {@code "PREMIUM_METRO"},
499	     * {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or {@code "STANDARD_REGIONAL"}. TIER is
500	     * {@code "PREMIUM"} when the {@link #getMembershipLevel() membership level} is 3 or more, otherwise
501	     * {@code "STANDARD"}. AREA is {@code "METRO"} when the {@link #getLocality() locality} is a known
502	     * region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise {@code "REGIONAL"}.
503	     */
504	    @Transient
505	    public String getOwnerSegment() {
506	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
507	        String area = REGION_POSTCODE_RANGES.containsKey(getLocality()) ? "METRO" : "REGIONAL";
508	        return tier + "_" + area;
509	    }
510	
511	    /** The IANA timezone name for {@code region} via the fixed region-to-timezone table, or
512	     *  {@code null} when the region carries no entry ({@code NSW -> Australia/Sydney},
513	     *  {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
514	    public static String timezoneForRegion(String region) {
515	        return REGION_TIMEZONES.get(region);
516	    }
517	
518	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
519	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
520	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
521	    public static int[] postcodeRangeForRegion(String region) {
522	        return REGION_POSTCODE_RANGES.get(region);
523	    }
524	
525	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
526	     *  absent, not a 4-digit value, or in no known range. */
527	    private static String regionForPostcode(String postcode) {
528	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
529	            return null;
530	        }
531	        int value = Integer.parseInt(postcode);
532	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
533	            int[] range = entry.getValue();
534	            if (value >= range[0] && value <= range[1]) {
535	                return entry.getKey();
536	            }
537	        }
538	        return null;
539	    }
540	
541	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
542	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
543	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
544	     *  {@code +1}), so a number matches at most one. */
545	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
546	        "+61", 9, "+1", 10);
547	
548	    /**
549	     * The stored E.164 {@link #telephone} formatted for humans, derived on read: the country code, a
550	     * space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). Falls back
551	     * to the raw value when it is {@code null} or begins with no recognised country code.
552	     */
553	    @Transient
554	    public String getTelephoneDisplay() {
555	        if (this.telephone == null) {
556	            return null;
557	        }
558	        String countryCode = countryCodeOf(this.telephone);
559	        if (countryCode == null) {
560	            return this.telephone;
561	        }
562	        String national = this.telephone.substring(countryCode.length());
563	        StringBuilder grouped = new StringBuilder(countryCode);
564	        for (int i = 0; i < national.length(); i++) {
565	            if (i % 3 == 0) {
566	                grouped.append(' ');
567	            }
568	            grouped.append(national.charAt(i));
569	        }
570	        return grouped.toString();
571	    }
572	
573	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
574	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
575	    public static String countryCodeOf(String telephone) {
576	        if (telephone == null) {
577	            return null;
578	        }
579	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
580	            if (telephone.startsWith(countryCode)) {
581	                return countryCode;
582	            }
583	        }
584	        return null;
585	    }
586	
587	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
588	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
589	     *  {@code +1 => 10}). */
590	    public static Integer nationalNumberLength(String countryCode) {
591	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
592	    }
593	
594	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
595	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
596	     *  digit-free value yields {@code 0}. */
597	    private static int luhnCheckDigit(String value) {
598	        int sum = 0;
599	        boolean doubling = true;
600	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
601	            char c = value.charAt(i);
602	            if (c < '0' || c > '9') {
603	                continue;
604	            }
605	            int digit = c - '0';
606	            if (doubling) {
607	                digit *= 2;
608	                if (digit > 9) {
609	                    digit -= 9;
610	                }
611	            }
612	            sum += digit;
613	            doubling = !doubling;
614	        }
615	        return (10 - (sum % 10)) % 10;
616	    }
617	
618	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters; the
619	     *  upper-case rendering of {@link #sha256HexLower(String)}. */
620	    public static String sha256Hex(String input) {
621	        return sha256HexLower(input).toUpperCase(Locale.ROOT);
622	    }
623	
624	    /** The lower-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
625	    public static String sha256HexLower(String input) {
626	        try {
627	            byte[] digest = MessageDigest.getInstance("SHA-256")
628	                .digest(input.getBytes(StandardCharsets.UTF_8));
629	            StringBuilder sb = new StringBuilder(digest.length * 2);
630	            for (byte b : digest) {
631	                sb.append(String.format("%02x", b));
632	            }
633	            return sb.toString();
634	        }
635	        catch (NoSuchAlgorithmException e) {
636	            throw new IllegalStateException("SHA-256 not available", e);
637	        }
638	    }
639	
640	    protected Set<Pet> getPetsInternal() {
641	        if (this.pets == null) {
642	            this.pets = new HashSet<>();
643	        }
644	        return this.pets;
645	    }
646	
647	    protected void setPetsInternal(Set<Pet> pets) {
648	        this.pets = pets;
649	    }
650	
651	    public List<Pet> getPets() {
652	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
653	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
654	        return Collections.unmodifiableList(sortedPets);
655	    }
656	
657	    public void setPets(List<Pet> pets) {
658	        this.pets = new HashSet<>(pets);
659	    }
660	
661	    public void addPet(Pet pet) {
662	        getPetsInternal().add(pet);
663	        pet.setOwner(this);
664	    }
665	
666	    /**
667	     * Return the Pet with the given name, or null if none found for this Owner.
668	     *
669	     * @param name to test
670	     * @return true if pet name is already in use
671	     */
672	    public Pet getPet(String name) {
673	        return getPet(name, false);
674	    }
675	
676	    /**
677	     * Return the Pet with the given name, or null if none found for this Owner.
678	     *
679	     * @param name to test
680	     * @return true if pet name is already in use
681	     */
682	    public Pet getPet(String name, boolean ignoreNew) {
683	        name = name.toLowerCase();
684	        for (Pet pet : getPetsInternal()) {
685	            if (!ignoreNew || !pet.isNew()) {
686	                String compName = pet.getName();
687	                compName = compName.toLowerCase();
688	                if (compName.equals(name)) {
689	                    return pet;
690	                }
691	            }
692	        }
693	        return null;
694	    }
695	
696	    public Pet getPet(Integer petId) {
697	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
698	    }
699	
700	    @Override
701	    public String toString() {
702	        return new ToStringCreator(this)
703	
704	            .append("id", this.getId())
705	            .append("new", this.isNew())
706	            .append("lastName", this.getLastName())
707	            .append("firstName", this.getFirstName())
708	            .append("address", this.address)
709	            .append("city", this.city)
710	            .append("telephone", this.telephone)
711	            .toString();
712	    }
