64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /** Dedicated audit logger; a successful create emits one line here. */
70	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
71	
72	    /** Monotonically increasing sequence number stamped onto each structured {@link OwnerCreatedEvent}. */
73	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
74	        new java.util.concurrent.atomic.AtomicLong();
75	
76	    /** Request header carrying the client-supplied key that makes a create idempotent. */
77	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
78	
79	    /**
80	     * Idempotency-Key -> id of the owner originally created under that key. A repeat create carrying an
81	     * already-seen key returns that owner rather than creating a duplicate. Only successful creates are
82	     * recorded here, and the key space is client-supplied, so the map is bounded by distinct keys seen.
83	     */
84	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
85	
86	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
87	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
88	
89	    /** Disposable email domains that are not accepted for an owner's email; a create with one is rejected. */
90	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
91	        "mailinator.com", "tempmail.com", "guerrillamail.com");
92	
93	    private final ClinicService clinicService;
94	
95	    private final OwnerMapper ownerMapper;
96	
97	    private final PetMapper petMapper;
98	
99	    private final VisitMapper visitMapper;
