126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
129	        return withOwner(ownerId, owner ->
130	            new ResponseEntity<>(buildOwnerDto(owner), HttpStatus.OK));
131	    }
132	
133	    /**
134	     * Look up the owner identified by {@code ownerId} and, when it exists, produce the response with
135	     * {@code onFound}; when no such owner exists, short-circuit with {@code 404 NOT_FOUND}. Centralizes
136	     * the fetch-and-guard shared by the single-owner endpoints so it is written once, not copied.
137	     */
138	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> onFound) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        return onFound.apply(owner);
144	    }
