146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
149	        String idempotencyKey = currentIdempotencyKey();
150	        if (idempotencyKey != null) {
151	            Integer existingId = idempotentCreates.get(idempotencyKey);
152	            if (existingId != null) {
153	                Owner existing = this.clinicService.findOwnerById(existingId);
154	                if (existing != null) {
155	                    return new ResponseEntity<>(buildOwnerDto(existing), HttpStatus.OK);
156	                }
157	            }
158	        }
159	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
160	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
161	                && response.getBody() != null && response.getBody().getId() != null) {
162	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
163	        }
164	        return response;
165	    }
166	
167	    /**
168	     * The non-blank {@code Idempotency-Key} header on the current request, or {@code null} when the
169	     * header is absent or blank. Read from the ambient request rather than the handler signature so the
170	     * generated {@link OwnersApi#addOwner} contract stays unchanged.
171	     */
172	    private static String currentIdempotencyKey() {
173	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs) {
174	            String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
175	            if (key != null && !key.isBlank()) {
176	                return key;
177	            }
178	        }
179	        return null;
180	    }
181	
182	    /**
183	     * Run the create pipeline for a new owner from its submitted fields and return the response: the
184	     * fields are mapped, normalized and validated, the registration date is resolved, the per-day,
185	     * identity and per-city gates are applied, the derived registration attributes are
186	     * assigned and the owner is saved and audited, yielding {@code 201 CREATED} with the new owner and
187	     * its {@code Location}. A gate that trips short-circuits with its own status ({@code 400},
188	     * {@code 429} or {@code 409}) and no owner is created. This is the single place an owner is created;
189	     * {@link #addOwner} is the thin entry point that delegates here, so request-level concerns stay out
190	     * of the create pipeline.
191	     */
192	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
193	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
194	        if (!normalizeAndValidateFields(owner)) {
195	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
196	        }
197	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
198	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
199	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
200	        }
201	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
202	        owner.setRegistrationDate(registrationDate);
203	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
204	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
205	        }
206	        owner.setHouseholdId(householdId(owner));
207	        owner.setIdentityKey(identityKey(owner));
208	        if (isDuplicate(owner)) {
209	            return new ResponseEntity<>(HttpStatus.CONFLICT);
210	        }
211	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
212	        if (countOwnersInCity(owner.getCity()) >= 50) {
213	            return new ResponseEntity<>(HttpStatus.CONFLICT);
214	        }
215	        assignRegistrationAttributes(owner, sharesHousehold);
216	        this.clinicService.saveOwner(owner);
217	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
218	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
219	            owner.getMembershipNumber());
220	        AUDIT.info(OwnerCreatedEvent.of(AUDIT_EVENT_SEQ.incrementAndGet(), owner).toJson());
221	        HttpHeaders headers = new HttpHeaders();
222	        headers.setLocation(UriComponentsBuilder.newInstance()
223	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
224	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
225	    }
226	
227	    /**
228	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
229	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
230	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
231	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
232	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
233	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
234	     */
235	    private boolean normalizeAndValidateFields(Owner owner) {
236	        if (!normalizeAddressFields(owner)) {
237	            return false;
238	        }
239	        if (owner.getEmail() != null) {
240	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
241	            if (!EMAIL_PATTERN.matcher(email).matches()) {
242	                return false;
243	            }
244	            if (isDisposableEmailDomain(email)) {
245	                return false;
246	            }
247	            owner.setEmail(email);
248	        }
249	        if (!isPostcodeValidForCity(owner)) {
250	            return false;
251	        }
252	        String telephone = normalizeTelephone(owner.getTelephone());
253	        if (telephone == null) {
254	            return false;
255	        }
256	        owner.setTelephone(telephone);
257	        return true;
258	    }
259	
260	    /**
261	     * Canonicalize an incoming owner's submitted address into its stored form and validate it,
262	     * returning whether the owner may proceed to creation. The structured fields are preferred when
263	     * present: when {@code addressLine1} is non-blank the structured lines are each normalized
264	     * ({@link #normalizeAddress}) and written back, and the flat {@code address} is set to the
265	     * composed value (the normalized addressLine1, with a single space and the normalized
266	     * addressLine2 appended when addressLine2 is present). Otherwise the flat {@code address} is
267	     * normalized and written back for backward compatibility. Returns {@code false} - so the caller
268	     * can reject the request with {@code 400 BAD_REQUEST} - when neither form supplies a non-blank
269	     * address. This is the single place the owner's address is read, canonicalized and written back,
270	     * mirroring the per-concern normalization the email, postcode and telephone steps each own.
271	     */
272	    private boolean normalizeAddressFields(Owner owner) {
273	        String line1 = normalizeAddress(owner.getAddressLine1());
274	        if (!line1.isEmpty()) {
275	            String line2 = normalizeAddress(owner.getAddressLine2());
276	            owner.setAddressLine1(line1);
277	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
278	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
279	            return true;
280	        }
281	        String address = normalizeAddress(owner.getAddress());
282	        if (address.isEmpty()) {
283	            return false;
284	        }
285	        owner.setAddress(address);
286	        return true;
287	    }
288	
289	    /**
290	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
291	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
292	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
293	     */
294	    private static boolean isDisposableEmailDomain(String email) {
295	        int at = email.lastIndexOf('@');
296	        if (at < 0) {
297	            return false;
298	        }
299	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
300	    }
301	
302	    /**
303	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
304	     * computed against the owner population rather than carried on the owner itself (currently the
305	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
306	     * listing intentionally omits these flags.
307	     */
308	    private OwnerDto buildOwnerDto(Owner owner) {
309	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
310	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
311	        ownerDto.setCapacityWarning(isCapacityWarning(owner));
312	        return ownerDto;
313	    }
314	
315	    /**
316	     * Whether {@code owner}'s city is approaching its per-city capacity limit: it already holds between
317	     * 40 and 49 other owners, one short of the hard limit of 50 at which creation is rejected.
318	     * Surfaced on responses as {@code capacityWarning}. Computed against the current owner population
319	     * excluding this owner, so the count basis mirrors the per-city create gate (which counts the
320	     * owners already present, before the new one is added).
321	     */
322	    private boolean isCapacityWarning(Owner owner) {
323	        long othersInCity = countOtherOwnersInCity(owner);
324	        return othersInCity >= 40 && othersInCity < 50;
325	    }
326	
327	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
328	    @Override
329	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
330	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
331	        if (currentOwner == null) {
332	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
333	        }
334	        currentOwner.setAddress(ownerFieldsDto.getAddress());
335	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
336	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
337	        currentOwner.setCity(ownerFieldsDto.getCity());
338	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
339	        currentOwner.setLastName(ownerFieldsDto.getLastName());
340	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
341	        String email = ownerFieldsDto.getEmail();
342	        if (email != null) {
343	            email = email.trim().toLowerCase(Locale.ROOT);
344	            if (!EMAIL_PATTERN.matcher(email).matches()) {
345	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
346	            }
347	        }
348	        currentOwner.setEmail(email);
349	        this.clinicService.saveOwner(currentOwner);
350	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
351	    }
352	
353	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
354	    @Transactional
355	    @Override
356	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
357	        return withOwner(ownerId, owner -> {
358	            owner.setDeleted(true);
359	            this.clinicService.saveOwner(owner);
360	            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
361	        });
362	    }
