428	
429	    /** Matches a well-formed postcode: exactly 4 digits. */
430	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
431	
432	    /**
433	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
434	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
435	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
436	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
437	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
438	     */
439	    private static boolean isPostcodeValidForCity(Owner owner) {
440	        String postcode = owner.getPostcode();
441	        if (postcode == null) {
442	            return true;
443	        }
444	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
445	            return false;
446	        }
447	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
448	        if (range == null) {
449	            return true;
450	        }
451	        int value = Integer.parseInt(postcode);
452	        return value >= range[0] && value <= range[1];
453	    }
454	
455	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
456	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
457	
458	    /**
459	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
460	     * code are kept when present; otherwise country code '+61' is assumed and a single
461	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
462	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
463	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
464	     * Returns {@code null} when the number cannot form a valid E.164 value.
465	     */
466	    private static String normalizeTelephone(String telephone) {
467	        if (telephone == null) {
468	            return null;
469	        }
470	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
471	        String e164;
472	        if (cleaned.startsWith("+")) {
473	            e164 = cleaned;
474	        } else {
475	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
476	            e164 = "+61" + national;
477	        }
478	        if (!E164_PATTERN.matcher(e164).matches()) {
479	            return null;
480	        }
481	        return hasValidNationalNumberLength(e164) ? e164 : null;
482	    }
483	
484	    /**
485	     * Whether the national number of a well-formed E.164 value has the length required for its
486	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
487	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
488	     */
489	    private static boolean hasValidNationalNumberLength(String e164) {
490	        String countryCode = Owner.countryCodeOf(e164);
491	        if (countryCode == null) {
492	            return true;
493	        }
494	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
495	    }
496	
497	    /**
498	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
499	     * code, membership number, household id, namesake count and household member count. Each is
500	     * derived from the owner's already-normalized fields and the existing owner population, so this
501	     * must run before the owner is saved, while the counts still exclude the owner being created.
502	     *
503	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
504	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
505	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
506	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
507	     */
508	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
509	        owner.setCustomerCode(generateCustomerCode(owner));
510	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
511	        owner.setHouseholdId(householdId(owner));
512	        owner.setNamesakeCount(countNamesakes(owner));
513	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
514	        owner.setMembershipLevelCap(membershipLevelCapForHousehold(owner));
515	        if (declaredMember) {
516	            owner.setPossibleDuplicate(false);
517	            owner.setPossibleDuplicateOf(null);
518	        } else {
519	            assignPossibleDuplicate(owner);
520	        }
521	    }
522	
523	    /**
524	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
525	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's postcode
526	     * and last-name {@link #soundex(String) Soundex} yet resolves to a different {@link #identityKey}.
527	     * Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf} to the
528	     * matching owner's id. Runs before save, against the existing owner population.
529	     */
530	    private void assignPossibleDuplicate(Owner owner) {
531	        Integer matchId = findPossibleDuplicateOf(owner);
532	        owner.setPossibleDuplicate(matchId != null);
533	        owner.setPossibleDuplicateOf(matchId);
534	    }
535	
536	    /**
537	     * The id of an existing owner that shares {@code owner}'s postcode and last-name
538	     * {@link #soundex(String) Soundex} but resolves to a different {@link #identityKey}, or
539	     * {@code null} when there is none. Because the telephone is part of the identity key, two owners
540	     * with the same last name and postcode but different telephones differ in key and so match here,
541	     * making the later a soft (possible) duplicate rather than a hard conflict. When several match,
542	     * the lowest id is returned. An owner without a postcode never matches.
543	     */
544	    private Integer findPossibleDuplicateOf(Owner owner) {
545	        String postcode = owner.getPostcode();
546	        if (postcode == null) {
547	            return null;
548	        }
549	        String soundex = soundex(owner.getLastName());
550	        String identityKey = owner.getIdentityKey();
551	        return this.clinicService.findAllOwners().stream()
552	            .filter(existing -> !existing.isDeleted())
553	            .filter(existing -> existing.getId() != null
554	                && postcode.equals(existing.getPostcode())
555	                && soundex(existing.getLastName()).equals(soundex)
556	                && !identityKey.equals(existing.getIdentityKey()))
557	            .map(Owner::getId)
558	            .min(Integer::compareTo)
559	            .orElse(null);
560	    }
561	
562	    /**
563	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
564	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
565	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
566	     * owner's last name (e.g. 'NSW-1A2B3C4D'). The identity is otherwise a pure function of the
567	     * region and the (telephone, last name) pair; only when the computed code collides with an
568	     * existing owner's customer code is it de-duplicated by appending '-<n>' with the smallest
569	     * {@code n} of 2 or more that makes it unique (e.g. 'NSW-1A2B3C4D-2').
570	     */
571	    private String generateCustomerCode(Owner owner) {
572	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
573	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
574	        String hash8 = Owner.sha256Hex(telephone + lastName).substring(0, 8);
575	        String base = owner.getRegion() + "-" + hash8;
576	        return deduplicateCustomerCode(base);
577	    }
578	
579	    /**
580	     * De-duplicate a computed customer code against the existing owner population: when {@code base}
581	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
582	     * {@code n} of 2 or more that yields a code no existing owner carries.
583	     */
584	    private String deduplicateCustomerCode(String base) {
585	        Set<String> existing = this.clinicService.findAllOwners().stream()
586	            .map(Owner::getCustomerCode)
587	            .filter(code -> code != null)
588	            .collect(java.util.stream.Collectors.toSet());
589	        if (!existing.contains(base)) {
590	            return base;
591	        }
592	        int n = 2;
593	        while (existing.contains(base + "-" + n)) {
594	            n++;
595	        }
596	        return base + "-" + n;
597	    }
598	
599	    /**
600	     * The number of existing owners registered in {@code city}, compared case-insensitively
601	     * with collapsed whitespace.
602	     */
603	    private int countOwnersInCity(String city) {
604	        String normalized = normalizeHouseholdField(city);
605	        return (int) this.clinicService.findAllOwners().stream()
606	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
607	            .count();
608	    }
609	
610	    /**
611	     * The number of existing owners in {@code owner}'s city other than {@code owner} itself, compared
612	     * case-insensitively with collapsed whitespace. This is the count of owners already present in the
613	     * city that a newly created owner joins, mirroring the basis of the per-city create gate.
614	     */
615	    private long countOtherOwnersInCity(Owner owner) {
616	        String normalized = normalizeHouseholdField(owner.getCity());
617	        return this.clinicService.findAllOwners().stream()
618	            .filter(existing -> existing.getId() == null || !existing.getId().equals(owner.getId()))
619	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
620	            .count();
621	    }
622	
623	    /**
624	     * The effective registration date to store for a new owner: the date supplied on the request
625	     * when present, otherwise the current server date, in either case rolled forward to a business
626	     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
627	     * This single point of resolution is what every registration-date-derived value (the stored
628	     * date, the membership number's year segment, the per-day create-limit) is computed from.
629	     */
630	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
631	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
632	        return toBusinessDay(date);
633	    }
634	
635	    /**
636	     * The fixed list of public holidays that a registration date must not fall on. A date landing
637	     * on one of these is rolled forward, exactly as weekends are.
638	     */
639	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
640	        LocalDate.of(2026, 1, 1),
641	        LocalDate.of(2026, 1, 26),
642	        LocalDate.of(2026, 4, 25),
643	        LocalDate.of(2026, 12, 25),
644	        LocalDate.of(2026, 12, 28));
645	
646	    /**
647	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
648	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
649	     * unchanged.
650	     */
651	    private static LocalDate toBusinessDay(LocalDate date) {
652	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
653	                || PUBLIC_HOLIDAYS.contains(date)) {
654	            date = date.plusDays(1);
655	        }
656	        return date;
657	    }
658	
659	    /**
660	     * Build the membership number '<customerCode>-M<YY>' where YY is the
661	     * {@link #membershipYearSegment(LocalDate) fiscal-year segment} of the {@code registrationDate}
662	     * (e.g. 'NSW-1A2B3C4D-M27').
663	     */
664	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
665	        return customerCode + "-M" + membershipYearSegment(registrationDate);
666	    }
667	
668	    /**
669	     * The two-digit year segment stamped into a membership number: the last two digits of the
670	     * fiscal year (starting 1 July) that contains the business-day-adjusted {@code registrationDate},
671	     * zero-padded (e.g. a date of 2026-09-05 falls in fiscal year 2027 -> '27'). Shares the
672	     * fiscal-year rule with {@link Owner#getFiscalYear()} via {@link Owner#fiscalYear(LocalDate)}.
673	     */
674	    private static String membershipYearSegment(LocalDate registrationDate) {
675	        return String.format("%02d", Owner.fiscalYear(registrationDate) % 100);
676	    }
677	
678	    /**
679	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
680	     * last name, compared case-insensitively.
681	     */
682	    private int countNamesakes(Owner owner) {
683	        String firstName = normalizeHouseholdField(owner.getFirstName());
684	        String lastName = normalizeHouseholdField(owner.getLastName());
685	        return (int) this.clinicService.findAllOwners().stream()
686	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
687	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
688	            .count();
689	    }
690	
691	    /**
692	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
693	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
694	     * unusually high daily signup volume.
695	     */
696	    private boolean isBulkSignupWarning() {
697	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
698	    }
699	
700	    /** The number of existing owners whose registration date is {@code date}. */
701	    private int countOwnersRegisteredOn(LocalDate date) {
702	        return (int) this.clinicService.findAllOwners().stream()
703	            .filter(existing -> date.equals(existing.getRegistrationDate()))
704	            .count();
705	    }
706	
707	    /**
708	     * The single derived key all duplicate detection flows through: the lower-case hex SHA-256 of
709	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, formed from the
710	     * owner's already-normalized fields (the email is already lower-cased, the telephone already in
711	     * E.164 form, and the last name reduced to its {@link #soundex(String) Soundex} code). Because
712	     * the telephone is part of the key, two owners with the same last name and postcode but
713	     * different telephones resolve to different keys and are both allowed (the later one becoming a
714	     * possible duplicate rather than a hard conflict).
715	     */
716	    private static String identityKey(Owner owner) {
717	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
718	        String email = owner.getEmail() == null ? "" : owner.getEmail();
719	        String key = telephone + "|" + email + "|" + soundex(owner.getLastName());
720	        return Owner.sha256HexLower(key);
721	    }
722	
723	    /**
724	     * Whether {@code owner}'s {@link #identityKey} equals a non-deleted existing owner's, which is
725	     * the sole duplicate condition: the previously separate telephone, email and household checks -
726	     * including the household-duplicate check derived from the {@code householdId} - are now all
727	     * expressed through this one identity key, so only an exact key match is a duplicate and a create
728	     * that trips it is rejected with {@code 409 CONFLICT}. Soft-deleted owners are ignored.
729	     */
730	    private boolean isDuplicate(Owner owner) {
731	        String key = owner.getIdentityKey();
732	        return this.clinicService.findAllOwners().stream()
733	            .filter(existing -> !existing.isDeleted())
734	            .map(Owner::getIdentityKey)
735	            .filter(existing -> existing != null)
736	            .anyMatch(key::equals);
737	    }
738	
739	    /** Common street-type abbreviations expanded during address normalization. */
740	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
741	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
742	
743	    /**
744	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
745	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
746	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
747	     * string when {@code address} is null or blank after normalization.
748	     */
749	    private static String normalizeAddress(String address) {
750	        if (address == null) {
751	            return "";
752	        }
753	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
754	        if (collapsed.isEmpty()) {
755	            return "";
756	        }
757	        StringBuilder sb = new StringBuilder(collapsed.length());
758	        for (String token : collapsed.split(" ")) {
759	            if (sb.length() > 0) {
760	                sb.append(' ');
761	            }
762	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
763	        }
764	        return sb.toString();
765	    }
766	
767	    /**
768	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
769	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
770	     */
771	    private static String normalizeHouseholdField(String value) {
772	        if (value == null) {
773	            return "";
774	        }
775	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
776	    }
777	
778	    /**
779	     * The American Soundex code of {@code value}: the retained first letter followed by up to three
780	     * digits encoding the remaining consonants, right-padded with zeros to length four. Non-letters
781	     * are ignored, adjacent letters coding to the same digit (including when separated by 'H' or 'W')
782	     * are coded once, and vowels (with 'Y') act as separators. Returns the empty string when
783	     * {@code value} holds no letters. Phonetically similar last names share a code, which is what the
784	     * identity key and the possible-duplicate soft match compare on.
785	     */
786	    private static String soundex(String value) {
787	        if (value == null) {
788	            return "";
789	        }
790	        StringBuilder letters = new StringBuilder();
791	        for (char c : value.toCharArray()) {
792	            if (c < 128 && Character.isLetter(c)) {
793	                letters.append(Character.toUpperCase(c));
794	            }
795	        }
796	        if (letters.length() == 0) {
797	            return "";
798	        }
799	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
800	        char previous = soundexDigit(letters.charAt(0));
801	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
802	            char c = letters.charAt(i);
803	            if (c == 'H' || c == 'W') {
804	                continue;
805	            }
806	            char digit = soundexDigit(c);
807	            if (digit != '0' && digit != previous) {
808	                code.append(digit);
809	            }
810	            previous = digit;
811	        }
812	        while (code.length() < 4) {
813	            code.append('0');
814	        }
815	        return code.toString();
816	    }
817	
818	    /** The Soundex digit for an upper-case letter, or {@code '0'} for letters that are not coded. */
819	    private static char soundexDigit(char c) {
820	        switch (c) {
821	            case 'B': case 'F': case 'P': case 'V':
822	                return '1';
823	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
824	                return '2';
825	            case 'D': case 'T':
826	                return '3';
827	            case 'L':
828	                return '4';
829	            case 'M': case 'N':
830	                return '5';
831	            case 'R':
832	                return '6';
833	            default:
834	                return '0';
835	        }
836	    }
837	
838	    /**
839	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
840	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
841	     * key rather than re-derived from the underlying fields here, so the household is described in one
842	     * place and every household-keyed value stays consistent with it.
843	     */
844	    private List<Owner> findHousemates(Owner owner) {
845	        String householdId = householdId(owner);
846	        return this.clinicService.findAllOwners().stream()
847	            .filter(existing -> !existing.isDeleted())
848	            .filter(existing -> householdId(existing).equals(householdId))
849	            .toList();
850	    }
851	
852	    /**
853	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
854	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
855	     */
856	    private int countHouseholdMembers(Owner owner) {
857	        return findHousemates(owner).size() + 1;
858	    }
859	
860	    /**
861	     * The membership level ceiling for a newly registered {@code owner}, derived from the household it
862	     * joins: one above the current maximum {@link Owner#getMembershipLevel() membershipLevel} among the
863	     * existing housemates (owners sharing the same {@code householdId}), so a new owner's reported level
864	     * can never exceed one above the household's current best. Returns {@code null} - meaning no ceiling
865	     * applies - when the owner has no existing household member.
866	     */
867	    private Integer membershipLevelCapForHousehold(Owner owner) {
868	        OptionalInt maxLevel = findHousemates(owner).stream()
869	            .mapToInt(Owner::getMembershipLevel)
870	            .max();
871	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
872	    }
873	
874	    /**
875	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
876	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
877	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
878	     * string standing in for a missing postcode), so housemates always resolve to the same value
879	     * regardless of registration order, and owners sharing a last name and postcode share it
880	     * automatically.
881	     */
882	    private static String householdId(Owner owner) {
883	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
884	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
885	        return Owner.sha256Hex(key).substring(0, 12);
886	    }
887	}
